<?php
declare(strict_types=1); session_start(); require_once __DIR__.'/config.php';
$error=null; function h(string $v): string { return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
if($_SERVER['REQUEST_METHOD']==='POST'){
 $email=strtolower(trim((string)($_POST['email']??''))); $password=(string)($_POST['password']??'');
 try{$q=db()->prepare('SELECT u.id,u.cafe_id,u.email,u.password_hash,c.name FROM users u JOIN cafes c ON c.id=u.cafe_id WHERE u.email=? AND u.role=? LIMIT 1');$q->execute([$email,'owner']);$u=$q->fetch();
 if($u && password_verify($password,$u['password_hash'])){session_regenerate_id(true);$_SESSION['owner_id']=(int)$u['id'];$_SESSION['cafe_id']=(int)$u['cafe_id'];$_SESSION['owner_email']=$u['email'];$_SESSION['cafe_name']=$u['name'];header('Location: owner.php');exit;}
 $error='Email or password is incorrect.';
 }catch(PDOException $e){error_log('CMS login: '.$e->getMessage());$error='Database setup failed. Check config.php and import schema.sql.';}
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CMS Café — Sign in</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;padding:22px;background:#101310;color:#f4f7f1;font:16px/1.5 system-ui}.panel{width:min(100%,430px);padding:26px;background:#1a201b;border:1px solid #303b32;border-radius:18px}label{display:block;margin:16px 0 6px}input{box-sizing:border-box;width:100%;padding:12px;background:#101510;color:white;border:1px solid #3a463b;border-radius:9px;font:inherit}button{width:100%;padding:13px;margin-top:20px;background:#b8ef83;border:0;border-radius:9px;font-weight:800}.muted{color:#aab5a9;font-size:13px}.error{background:#512b2b;padding:10px;border-radius:9px}a{color:#b8ef83}</style></head><body><main class="panel"><h1>Owner sign in</h1><p class="muted">Use your café owner email.</p><?php if($error):?><p class="error"><?=h($error)?></p><?php endif;?><form method="post"><label for="email">Email</label><input id="email" type="email" name="email" required autocomplete="username" value="<?=h((string)($_POST['email']??''))?>"><label for="password">Password</label><input id="password" type="password" name="password" required autocomplete="current-password"><button>Sign in</button></form><p class="muted"><a href="index.php">Create café account</a></p></main></body></html>
